LAYER
  NAME "c_atencion_ivea_2025_inc_alfa"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom, inc_alfa FROM ivea.resultados_por_municipio_2025 WHERE the_geom && !BOX!) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Resultados de incorporación en alfabetización"
    "wms_enable_request" "*"
  END
  CLASS
    NAME "nulo"
    EXPRESSION ([inc_alfa] = 0)
    STYLE
      OUTLINECOLOR 80 80 80
      WIDTH 0.8
      OPACITY 60
      COLOR 80 80 80
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "bajo"
    EXPRESSION ([inc_alfa] >1 and [inc_alfa] <=0.0)
    STYLE
      OUTLINECOLOR 0 128 0
      WIDTH 0.8
      OPACITY 60
      COLOR 0 128 0
    END
    LABEL
      FONT "arial"
      SIZE 10
      COLOR 0 0 0
      OUTLINECOLOR 255 255 255
      BUFFER 5
      POSITION uc
      TYPE truetype
    END
  END
  CLASS
    NAME "medio"
    EXPRESSION ([inc_alfa] >0.0 and [inc_alfa] <=1.5)
    STYLE
      OUTLINECOLOR 255 255 0
      WIDTH 0.8
